<section class="panel"><header class="panel-head"><div><span class="eyebrow">Receiving & quality acceptance</span><h2>Accepted inventory and controlled holds</h2></div><span class="panel-meta"><?= count($receipts) ?> receipt(s)</span></header><?php if(can('inventory.create')&&$poLines): ?><form class="compact-form" action="<?= h(app_url('fulfillment-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_receipt"><input type="hidden" name="purchase_order_id" value="<?= (int)$selected['id'] ?>"><label><span>Receipt number</span><input name="receipt_number" placeholder="Auto-generated"></label><label><span>Received at</span><input type="datetime-local" name="received_at" value="<?= h(date('Y-m-d\TH:i')) ?>"></label><label><span>PO line</span><select name="purchase_order_line_id" required><?php foreach($poLines as $line): $remaining=max(0,(float)$line['quantity_ordered']-(float)($acceptedMap[(int)$line['id']]['accepted']??0)); ?><option value="<?= (int)$line['id'] ?>"><?= h($line['description'].' · remaining '.number_format($remaining,4)) ?></option><?php endforeach; ?></select></label><label><span>Receiving location</span><select name="location_id" required><?php foreach($locations as $location): if((int)($location['company_id']??0)!==(int)$selected['company_id'])continue;$value=(int)($location['location_id']??$location['id']); ?><option value="<?= $value ?>"><?= h($location['name']) ?></option><?php endforeach; ?></select></label><label><span>Quantity received</span><input type="number" min="0.0001" step="0.0001" name="quantity_received" required></label><label><span>Quantity accepted</span><input type="number" min="0" step="0.0001" name="quantity_accepted" required></label><label><span>Quantity rejected / held</span><input type="number" min="0" step="0.0001" name="quantity_rejected" value="0" required></label><label><span>Condition</span><select name="condition_status"><?php foreach(fulfillment_conditions() as $value): ?><option value="<?= h($value) ?>"><?= h(status_label($value)) ?></option><?php endforeach; ?></select></label><label><span>Packing slip</span><input name="packing_slip_number"></label><label><span>Serial / lot</span><input name="serial_or_lot_reference"></label><label><span>Carrier</span><input name="carrier" value="<?= h($selected['carrier']) ?>"></label><label><span>Tracking number</span><input name="tracking_number" value="<?= h($selected['tracking_number']) ?>"></label><label class="span-2"><span>Inspection evidence</span><textarea name="notes" required></textarea></label><div class="span-2 inline-actions"><button class="button primary" type="submit">Post Accepted Receipt</button><small>Only accepted quantity updates inventory; rejected and held quantity creates quality evidence.</small></div></form><?php endif; ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Receipt</th><th>Line</th><th class="numeric">Received</th><th class="numeric">Accepted</th><th class="numeric">Rejected</th><th>Condition / evidence</th></tr></thead><tbody><?php foreach($receiptLines as $line): $poLine=fulfillment_find_po_line((int)$line['purchase_order_line_id']); ?><tr><td><strong><?= h($line['receipt_number']??('#'.$line['receipt_id'])) ?></strong><small><?= h(date_us(substr((string)$line['received_at'],0,10))) ?></small></td><td><?= h($poLine['description']??'Unknown PO line') ?></td><td class="numeric"><?= number_format((float)$line['quantity_received'],4) ?></td><td class="numeric"><strong><?= number_format((float)$line['quantity_accepted'],4) ?></strong></td><td class="numeric"><?= number_format((float)$line['quantity_rejected'],4) ?></td><td><?= badge($line['condition_status']) ?><small><?= h($line['serial_or_lot_reference']??'') ?> · <?= h($line['notes']) ?></small></td></tr><?php endforeach; ?><?php if(!$receiptLines): ?><tr><td colspan="6"><?php render_empty_state('No receipt lines','Record supplier delivery and inspection evidence before invoice matching.'); ?></td></tr><?php endif; ?></tbody></table></div></section>
